function sectionInfo(t,index=0){const content=t.closest('[id^="gadget-content-"],[data-testid*="gadget.content"],.dashboard-item-content')||t.parentElement;const id=(content?.id?.match(/gadget-content-(\d+)/)||[])[1]||(t.closest('[id^="gadget-"]')?.id.match(/gadget-(\d+)/)||[])[1]||'';const box=(id&&document.getElementById(`gadget-${id}`))||content.closest('[data-testid*="dashboard-item"],[id^="gadget-"],.dashboard-item,.portlet,section,article,[role="region"]')||content;const heading=id?document.querySelector(`#gadget-title-${CSS.escape(id)} [data-testid="dashboard-internal-common.ui.gadget.title-readonly.title-inner"],#gadget-title-${CSS.escape(id)} h2`):null;const fallback=[...box.querySelectorAll('[data-testid="dashboard-internal-common.ui.gadget.title-readonly.title-inner"],h1,h2,h3,h4,[role="heading"]')].find(e=>vis(e)&&txt(e).length<180);return{title:txt(heading)||txt(fallback)||box.getAttribute('aria-label')||(id?`Gadget ${id}`:`Section ${index+1}`),key:id?`gadget-${id}`:`section-${index+1}`,id,box,table:t}}
function range(box){const m=txt(box).match(/(\d+)\s*[–-]\s*(\d+)\s+of\s+(\d+)/i)||txt(box).match(/(\d+)\s+to\s+(\d+)\s+of\s+(\d+)/i);return m?{from:+m[1],to:+m[2],total:+m[3],pageSize:+m[2]-+m[1]+1}:null}
