async function waitPage(item,before,beforeRange){const start=Date.now();let last='',stable=0;while(Date.now()-start<state.settings.timeoutMs){if(state.abort?.signal.aborted)throw new DOMException('Cancelled','AbortError');await sleep(300);const replacement=[...item.box.querySelectorAll('table,[role="table"],[role="grid"]')].find(vis);if(replacement)item.table=replacement;const now=signature(item.table),nowRange=JSON.stringify(range(item.box)),busy=[...item.box.querySelectorAll('[aria-busy="true"],[class*="loading"],[class*="spinner"],[data-testid*="loading"]')].some(vis);if((now!==before||nowRange!==beforeRange)&&!busy&&now===last)stable+=300;else stable=0;last=now;if(stable>=state.settings.settleMs)return true}return false}
function header(rs){let best=null;rs.slice(0,20).forEach((r,i)=>{const score=r.filter(v=>/key|summary|assignee|parent|status|due|created|instances|vpat|owner/i.test(v)).length;if(!best||score>best.score)best={row:r,i,score}});return best?.score>=2?best:null}
