function compare(c,p){if(!p)return null;const set=a=>new Set(a.map(x=>x.key).filter(Boolean)),c7=set(c.due7),p7=set(p.due7),co=set(c.overdue),po=set(p.overdue);return{moduleDelta:c.modules.total-p.modules.total,unassignedModuleDelta:c.unassigned.moduleCount-p.unassigned.moduleCount,unassignedEvaluationDelta:c.unassigned.evaluationCount-p.unassigned.evaluationCount,dueAdded:[...c7].filter(x=>!p7.has(x)),dueRemoved:[...p7].filter(x=>!c7.has(x)),overdueAdded:[...co].filter(x=>!po.has(x)),overdueRemoved:[...po].filter(x=>!co.has(x))}}
function tempoHours(text){const v=String(text||'').trim().toLowerCase();let h=0;const hm=v.match(/(\d+(?:\.\d+)?)\s*h/),mm=v.match(/(\d+)\s*m/);if(hm)h+=+hm[1];if(mm)h+=+mm[1]/60;return h}
function isTempoPage(){return /\/jira\/apps\/.+\/planner\/resource/i.test(location.pathname)||!!document.querySelector('[data-testid^="user-column-"]')}
function scanTempoNative(){if(!isTempoPage())return false;const users=[...document.querySelectorAll('[data-testid^="user-column-"]')];if(!users.length)return false;const next={...state.tempoPlanning};for(const user of users){const raw=user.getAttribute('data-testid')||'',id=raw.replace(/^user-column-/,'');let row=user.parentElement;for(let depth=0;row&&depth<8&&!row.querySelector('[data-testid^="availability-column-"]');depth++)row=row.parentElement;const name=user.querySelector('img[alt]')?.getAttribute('alt')||txt(user.querySelector('[data-testid="resourcePlanningUserAvatar"] p'))||txt(user).split('CORE')[0].trim();const capMatch=txt(user).match(/\((\d+)%\)/),capacityPct=capMatch?+capMatch[1]:null;const avail=[...document.querySelectorAll('[data-testid^="availability-column-"]')].find(el=>(el.getAttribute('data-testid')||'').endsWith(id))||row?.querySelector('[data-testid^="availability-column-"]');const availableHours=tempoHours(txt(avail));if(name)next[name]={...(next[name]||{}),id,name,capacityPct:capacityPct??next[name]?.capacityPct,availableHours:avail?availableHours:(next[name]?.availableHours??0),scannedAt:new Date().toISOString()}}state.tempoPlanning=next;save(KEYS.tempoPlanning,state.tempoPlanning);state.status=`Tempo Planning updated: ${users.length} visible people.`;return true}
async function scan(){if(state.running)return;if(isTempoPage()){if(scanTempoNative()){render();return}state.status='Tempo Planning rows are not ready yet.';render();return;}const plan=inspect(),expected=plan.reduce((a,x)=>a+x.expected,0);if(!plan.length){state.status='Scan error: no supported tables found.';render();return}state.running=true;state.abort=new AbortController();state.progress={done:0,total:expected,section:'Preparing'};render();const sections=new Map(),warnings=[];try{for(const item of plan){const sec={title:item.title,key:item.key,expected:item.expected,pages:0,rows:[],seen:new Set()},seenPages=new Set();let page=1,limit=Math.min(state.settings.maxPages,Math.max(1,item.pages+2));while(page<=limit){const fp=fingerprint(item);if(seenPages.has(fp)){warnings.push(`${item.title}: repeated page detected at page ${page}; stopped to prevent a loop.`);break}seenPages.add(fp);mark(item.table,`Scanning ${item.title}, page ${page} of approximately ${item.pages}`);const dom=rowEls(item.table);dom.map(cells).forEach((r,i)=>{const a=directAssignee(dom[i]),enriched=a?[...r,`__ASSIGNEE__:${a}`]:r,key=enriched.join('␟');if(!sec.seen.has(key)){sec.seen.add(key);sec.rows.push(enriched);state.progress.done++;state.progress.section=item.title;updateProgress()}});sec.pages=page;const rg=range(item.box),captured=Math.max(0,sec.rows.length-1);if((rg&&rg.to>=rg.total)||captured>=item.expected)break;const next=safeNext(item);if(!next){warnings.push(`${item.title}: expected ${item.expected}, captured ${captured}; no safe Next control found.`);break}const before=signature(item.table),beforeRange=JSON.stringify(rg),beforeFp=fingerprint(item),url=location.href;mark(next,`Loading page ${page+1} of ${item.title}`);next.click();if(location.href!==url)throw new Error(`${item.title}: unsafe navigation detected.`);if(!await waitPage(item,before,beforeRange)){warnings.push(`${item.title}: Next activated but rows did not stabilize.`);break}const after=range(item.box);if(fingerprint(item)===beforeFp||(rg&&after&&after.from<=rg.from)){warnings.push(`${item.title}: pagination did not advance after page ${page}.`);break}page++}const captured=Math.max(0,sec.rows.length-1);if(captured<item.expected)warnings.push(`${item.title}: incomplete, expected ${item.expected}, captured ${captured}.`);sections.set(item.key,sec)}const result={name:pageName(),at:new Date().toISOString(),sections:[...sections.values()].map(s=>({title:s.title,kind:classify(s.title),pages:s.pages,rows:Math.max(0,s.rows.length-1),expected:s.expected,complete:Math.max(0,s.rows.length-1)>=s.expected})),warnings,report:report(sections)};const previous=state.history.map(h=>state.scans[h.id]).find(x=>x?.name===result.name&&x.report);result.changes=compare(result.report,previous?.report);const id=String(Date.now());state.scans[id]=result;state.history=[{id,name:result.name,at:result.at,rows:result.sections.reduce((a,x)=>a+x.rows,0)},...state.history].slice(0,30);save(KEYS.scans,state.scans);save(KEYS.history,state.history);state.status=warnings.length?`Scan completed with ${warnings.length} warning(s).`:`Scan complete: ${result.sections.length} sections.`}catch(e){state.status=e.name==='AbortError'?'Scan cancelled.':`Scan error: ${e.message}`}finally{state.running=false;state.progress=null;document.querySelectorAll('.doc-scan-focus').forEach(x=>x.classList.remove('doc-scan-focus'));render()}}
function updateProgress(){const p=document.querySelector('#doc-root progress'),s=document.querySelector('#doc-root .progress-text');if(p){p.max=Math.max(1,state.progress.total);p.value=Math.min(state.progress.done,state.progress.total)}if(s)s.textContent=`${state.progress.section}: ${state.progress.done} of approximately ${state.progress.total} rows`}
function parseCsv(src){const out=[];let row=[],cell='',q=false;for(let i=0;i<src.length;i++){const c=src[i],n=src[i+1];if(c==='"'&&q&&n==='"'){cell+='"';i++}else if(c==='"')q=!q;else if(c===','&&!q){row.push(cell);cell=''}else if((c==='\n'||c==='\r')&&!q){if(c==='\r'&&n==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))out.push(row);row=[];cell=''}else cell+=c}row.push(cell);if(row.some(x=>x.trim()))out.push(row);return out}
function importCapacity(src){const rows=parseCsv(src),hi=rows.findIndex(r=>r.some(c=>/consultant|employee|person|name/i.test(c)));if(hi<0)throw new Error('No consultant/name header found.');const hs=rows[hi].map(norm),find=ps=>hs.findIndex(h=>ps.some(p=>p.test(h))),ix={name:find([/consultant/,/employee/,/person/,/^name$/]),capacity:find([/testing capacity/,/^capacity/]),fto:find([/^fto$/, /pto/]),holiday:find([/holiday/]),sme:find([/sme hours/]),booked:find([/booked hours/,/^booked$/])};state.capacity=rows.slice(hi+1).map(r=>({name:(r[ix.name]||'').trim(),capacity:ix.capacity>=0?num(r[ix.capacity]):null,fto:ix.fto>=0?num(r[ix.fto]):0,holiday:ix.holiday>=0?num(r[ix.holiday]):0,sme:ix.sme>=0?num(r[ix.sme]):0,booked:ix.booked>=0?num(r[ix.booked]):0})).filter(x=>x.name&&!/total|available capacity|demand evals/i.test(x.name));save(KEYS.capacity,state.capacity);const present=new Set(state.team.map(x=>norm(x.name)));for(const c of state.capacity)if(!present.has(norm(c.name)))state.team.push({name:c.name,role:'member',aliases:[]});save(KEYS.team,state.team)}
function matchRoster(name){const n=norm(name);return state.team.find(p=>norm(p.name)===n||(p.aliases||[]).some(a=>norm(a)===n))}
function capacityFor(name){const p=matchRoster(name),c=state.capacity.find(x=>norm(x.name)===norm(p?.name||name))||{};return{name:p?.name||name,capacity:Number.isInteger(p?.capacity)?p.capacity:(c.capacity??state.settings.capacityTargetPct),fto:Number.isInteger(p?.fto)?p.fto:(c.fto||0),holiday:Number.isInteger(p?.holiday)?p.holiday:(c.holiday||0),sme:c.sme||0,booked:c.booked||0}}
function addBusinessDays(start,days){const d=new Date(start);let left=Math.max(0,Math.ceil(days));while(left>0){d.setDate(d.getDate()+1);if(d.getDay()!==0&&d.getDay()!==6)left--}return d}
function availability(name,r){const c=capacityFor(name),daily=Math.max(.1,state.settings.workdayHours*(c.capacity??state.settings.capacityTargetPct)/100),gross=state.settings.workdayHours*5*state.settings.planningWeeks,available=Math.max(0,gross-c.fto-c.holiday-c.sme),target=available*(c.capacity??state.settings.capacityTargetPct)/100,hours=(r.modules.byPerson[name]||0)*state.settings.moduleHours+(r.validations.byPerson[name]||0)*state.settings.findingHours+(r.vpats.byPerson[name]||0)*state.settings.vpatHours+(r.allSrs.hoursByPerson[name]||0)+c.booked+c.fto+c.holiday+c.sme;const tempo=r.tempo?.byPerson?.[name]||0;return{date:addBusinessDays(new Date(),hours/daily),hours,days:Math.ceil(hours/daily),available,target,tempo,gap:target-tempo}}
function latest(){return state.scans[state.history[0]?.id]}
function isManager(n){return isOperationalRole(n)}
function suggested(){const x=latest(),team=new Set(state.team.flatMap(p=>[p.name,...(p.aliases||[])]).map(norm)),dismissed=new Set(state.dismissed.map(norm));return(x?.report.records||[]).map(r=>r.assignee).filter(validPerson).filter((n,i,a)=>a.findIndex(x=>norm(x)===norm(n))===i&&!team.has(norm(n))&&!dismissed.has(norm(n)))}
function objectRows(obj,label){return Object.entries(obj).filter(([n])=>!isOperationalRole(n)).sort((a,b)=>b[1]-a[1]).map(([n,c])=>`<tr><th>${esc(n)}</th><td>${c}</td></tr>`).join('')||`<tr><td colspan="2">No ${label} data.</td></tr>`}
function serviceAssignmentCard(title,label,r){const rows=Object.entries(r.allSrs?.countsByPerson||{}).map(([person,types])=>[person,types[label]||0]).filter(([,count])=>count>0).sort((a,b)=>b[1]-a[1]);return`<section class="card"><h2>${esc(title)}</h2><table><thead><tr><th>Assignee</th><th>Requests</th></tr></thead><tbody>${rows.map(([person,count])=>`<tr><th>${esc(person)}</th><td>${count}</td></tr>`).join('')||`<tr><td colspan="2">No ${esc(label)} assignments.</td></tr>`}</tbody></table></section>`}
function planningIntelligence(r){return`<section class="card"><h2>Work-stage distribution</h2><div class="metric-grid">${Object.entries(r.stages).map(([name,count])=>`<div><strong>${count}</strong><span>${esc(name)}</span></div>`).join('')}</div></section><section class="card"><h2>Planning gaps</h2><p class="muted">Subtasks missing Start date, Due date, or Original estimate.</p><div class="scroll"><table><thead><tr><th>CORE</th><th>Summary</th><th>Assignee</th><th>Missing</th></tr></thead><tbody>${r.planningGaps.map(x=>`<tr><th>${esc(x.key||'—')}</th><td>${esc(x.summary||'—')}</td><td>${esc(x.assignee||'Unassigned')}</td><td>${esc(x.problems.join(', '))}</td></tr>`).join('')||'<tr><td colspan="4">No planning gaps detected.</td></tr>'}</tbody></table></div></section><section class="card"><h2>Validation estimate quality</h2><div class="scroll"><table><thead><tr><th>CORE</th><th>Findings</th><th>Expected</th><th>Original estimate</th><th>Result</th></tr></thead><tbody>${r.validationQA.map(x=>`<tr><th>${esc(x.key||'—')}</th><td>${x.findings}</td><td>${x.expected.toFixed(1)}h</td><td>${x.actual?`${x.actual.toFixed(1)}h`:'Missing'}</td><td>${esc(x.severity)}${x.variancePct===null?'':` (${x.variancePct>0?'+':''}${x.variancePct}%)`}</td></tr>`).join('')||'<tr><td colspan="5">No validation estimate issues detected.</td></tr>'}</tbody></table></div></section><section class="card"><h2>Possibly completed but still open</h2><table><tbody>${r.completionMismatch.map(x=>`<tr><th>${esc(x.key||'—')}</th><td>${esc(x.summary||'—')}</td><td>${esc(x.status||'No status')}</td></tr>`).join('')||'<tr><td colspan="3">No completion mismatches detected.</td></tr>'}</tbody></table></section>`}
function dashboard(){const x=latest();if(!x)return`<section class="card"><h2>No scan results</h2><p>Run Scan all pages to create operational views.</p></section>`;const r=x.report,c=x.changes;return`<section class="card"><h2>${esc(x.name)}</h2><p class="muted">${new Date(x.at).toLocaleString()}</p></section>${x.warnings.filter(w=>!(/^Tempo/i.test(x.name)&&/Section 1:.*captured 0/i.test(w))).map(w=>`<div class="notice">${esc(w)}</div>`).join('')}${c?`<section class="card"><h2>Changes since previous scan</h2><ul><li>Assigned pages/modules: ${c.moduleDelta>=0?'+':''}${c.moduleDelta}</li><li>Unassigned modules: ${c.unassignedModuleDelta>=0?'+':''}${c.unassignedModuleDelta}</li><li>Unassigned evaluations: ${c.unassignedEvaluationDelta>=0?'+':''}${c.unassignedEvaluationDelta}</li><li>Newly due within 7 days: ${c.dueAdded.length}</li><li>Newly overdue: ${c.overdueAdded.length}</li></ul></section>`:''}<div class="grid"><section class="card"><h2>Pages/modules assigned</h2><table><tbody>${objectRows(r.modules.byPerson,'module')}</tbody></table></section><section class="card"><h2>Findings assigned</h2><table><tbody>${objectRows(r.validations.byPerson,'finding')}</tbody></table></section><section class="card"><h2>VPATs assigned</h2><table><tbody>${objectRows(r.vpats.byPerson,'VPAT')}</tbody></table></section></div><div class="grid">${serviceAssignmentCard('Demand Validation assigned','Demand Validation',r)}${serviceAssignmentCard('Live Consultation assigned','Live Consultation',r)}${serviceAssignmentCard('Technical Question assigned','Technical Question',r)}</div><section class="card"><h2>Request owners</h2><table><tbody>${objectRows(r.owners,'owner')}</tbody></table></section><section class="card"><h2>Parent service requests</h2><p class="muted">Deduplicated from ALL SRs by CORE key; parent effort does not duplicate module, finding, or VPAT demand.</p><table><thead><tr><th>Service type</th><th>Count</th><th>Average hours</th><th>Estimated hours</th></tr></thead><tbody>${Object.entries(r.allSrs.counts).filter(([type])=>type!=='Other SR').sort((a,b)=>b[1]-a[1]).map(([type,count])=>`<tr><th>${esc(type)}</th><td>${count}</td><td>${Object.values(SERVICE_RULES).find(v=>v.label===type)?.hours??0}</td><td>${(count*(Object.values(SERVICE_RULES).find(v=>v.label===type)?.hours||0)).toFixed(2)}</td></tr>`).join('')||'<tr><td colspan="4">No ALL SRs data.</td></tr>'}</tbody><tfoot><tr><th colspan="3">Total estimated hours</th><td>${r.allSrs.estimatedHours.toFixed(2)}</td></tr><tr><th colspan="3">Estimated unassigned hours</th><td>${r.allSrs.unassignedHours.toFixed(2)}</td></tr></tfoot></table><details class="other-sr"><summary><strong>Other SR catch-all (${r.allSrs.other?.length||0})</strong><span class="chev">⌄</span></summary><div class="scroll"><table><thead><tr><th>CORE</th><th>Summary</th><th>Assignee</th></tr></thead><tbody>${(r.allSrs.other||[]).map(item=>`<tr><th>${esc(item.key||'—')}</th><td>${esc(item.summary||'—')}</td><td>${esc(item.assignee||'Unassigned')}</td></tr>`).join('')||'<tr><td colspan="3">No uncategorized service requests.</td></tr>'}</tbody></table></div></details></section><section class="card"><div class="section-heading"><h2>Team capacity</h2><button class="secondary" data-manage-team>Manage team</button></div><p class="muted">The next three weeks target 86% accountable time after FTO, holidays, SME commitments, and role exclusions. Availability is projected beyond the window from workload, service averages, testing capacity, FTO, holidays, SME time, and booked work.</p><div class="scroll"><table><thead><tr><th>Team member</th><th>First available</th><th>Pages/modules</th><th>Findings</th><th>VPATs</th><th>Estimated workload</th><th>Tempo planned</th><th>Tempo gap</th></tr></thead><tbody>${state.team.filter(p=>!['manager','coordinator'].includes(p.role)&&!NON_CAPACITY_NAMES.has(norm(p.name))).map(p=>{const a=availability(p.name,r),c=capacityFor(p.name);return{date:a.date,html:`<tr><th>${esc(p.name)}<small>${c.capacity}% testing capacity</small></th><td>${a.date.toLocaleDateString()}</td><td>${r.modules.byPerson[p.name]||0}</td><td>${r.validations.byPerson[p.name]||0}</td><td>${r.vpats.byPerson[p.name]||0}</td><td>${a.hours.toFixed(1)} hrs (${a.days} business days)</td><td>${a.tempo.toFixed(1)}h</td><td>${a.gap.toFixed(1)}h</td></tr>`}}).sort((a,b)=>a.date-b.date).map(x=>x.html).join('')||'<tr><td colspan="9">Configure roster or import capacity CSV.</td></tr>'}</tbody></table></div></section><section class="card"><h2>Unassigned queue</h2><p><strong>${r.unassigned.evaluationCount}</strong> evaluations · <strong>${r.unassigned.moduleCount}</strong> modules</p><table><tbody>${Object.values(r.unassigned.evaluations).sort((a,b)=>b.modules-a.modules).map(e=>`<tr><th>${esc(e.parent||e.id)}</th><td>${e.modules}</td><td>${e.needsAttention?'Assigned to Shane; setup needs attention':'—'}</td></tr>`).join('')||'<tr><td>No queue data.</td></tr>'}</tbody></table></section>${planningIntelligence(r)}<section class="card"><h2>Timeline and due-date attention</h2><p>${r.missing.items.length} missing/past timelines; ${r.missing.shane.length} assigned to Shane; ${r.overdue.length} overdue; ${r.due7.length} due in 7 days.</p></section>`}
function history(){return state.history.map(h=>{const x=state.scans[h.id];return`<article class="card record"><details><summary><span><strong>${esc(h.name)}</strong><small>${new Date(h.at).toLocaleString()} · ${x.sections.length} sections · ${h.rows} rows</small></span><span class="summary-actions"><span class="closed-label">View results</span><span class="open-label">Hide results</span><span class="chev" aria-hidden="true">⌄</span></span></summary><div class="scroll"><table><thead><tr><th>Section</th><th>Meaning</th><th>Pages</th><th>Captured / expected</th></tr></thead><tbody>${x.sections.map(s=>`<tr><th>${esc(s.title)}${s.complete?'':' ⚠'}</th><td>${esc(s.kind)}</td><td>${s.pages}</td><td>${s.rows} / ${s.expected}</td></tr>`).join('')}</tbody></table></div><div class="actions"><button class="secondary" data-view="${h.id}">View dashboard</button><button class="secondary" data-export="${h.id}">Export JSON</button><button class="danger" data-delete="${h.id}">Delete scan</button></div></details></article>`}).join('')||'<p>No scans recorded.</p>'}
function scanView(){const p=inspect(),total=p.reduce((a,x)=>a+x.expected,0);return`<section class="card"><h2>Scan dashboard</h2><p>Detected <strong>${p.length}</strong> sections and about <strong>${total}</strong> rows.</p><details><summary>Review detected sections</summary><ul>${p.map(x=>`<li>${esc(x.title)}: ${x.visible} visible, ${x.expected} expected</li>`).join('')}</ul></details>${state.running?`<div class="progress" role="status" aria-live="polite"><strong>Scan in progress</strong><progress max="${state.progress?.total||1}" value="${state.progress?.done||0}"></progress><span class="progress-text">Preparing</span></div>`:''}<div class="actions"><button data-scan ${state.running?'disabled':''}>Scan all pages</button><button class="secondary" data-cancel ${!state.running?'disabled':''}>Cancel</button></div></section><h2>Scan history</h2>${history()}`}
function settingsView(){const list=suggested();return`<section class="card"><h2>Team roster</h2><table><thead><tr><th>Name</th><th>Role</th><th>Capacity %</th><th>FTO hours</th><th>Holiday hours</th><th>Aliases</th><th>Action</th></tr></thead><tbody>${state.team.map((p,i)=>`<tr><th>${esc(p.name)}</th><td>${p.role==='manager'?'Manager':p.role==='coordinator'?'Delivery Coordinator':'Team member'}</td><td><label><span class="sr-only">Capacity percentage for ${esc(p.name)}</span><input data-team-capacity="${i}" type="number" min="0" max="100" step="1" value="${Number.isInteger(p.capacity)?p.capacity:100}"></label></td><td><label><span class="sr-only">FTO hours for ${esc(p.name)}</span><input data-team-fto="${i}" type="number" min="0" step="1" value="${Number.isInteger(p.fto)?p.fto:0}"></label></td><td><label><span class="sr-only">Holiday hours for ${esc(p.name)}</span><input data-team-holiday="${i}" type="number" min="0" step="1" value="${Number.isInteger(p.holiday)?p.holiday:0}"></label></td><td>${esc((p.aliases||[]).join(', ')||'—')}</td><td class="right"><button class="secondary" data-remove-roster="${i}">Remove</button></td></tr>`).join('')||'<tr><td colspan="7">No roster configured.</td></tr>'}</tbody></table><p class="helper"><strong>Capacity %:</strong> Reduce this when a team member must keep delivery time open, has dedicated SME responsibilities, or is assigned to internal projects. FTO and Holiday fields accept whole hours only.</p><div class="actions"><button data-save-team>Save team adjustments</button></div><label>Add person<input id="manual-name"></label><label>Aliases, comma separated<input id="manual-aliases"></label><div class="actions"><button data-add-manual>Add team member</button><button class="secondary" data-add-manager>Add manager</button><button class="secondary" data-add-coordinator>Add Delivery Coordinator</button></div></section><section class="card"><h2>Capacity CSV</h2><label>Import capacity planner CSV<input id="capacity-csv" type="file" accept=".csv,text/csv"></label></section><section class="card"><h2>Suggested team members</h2><table><thead><tr><th><label class="inline"><input type="checkbox" data-select-all> Select all assignees</label></th><th>State</th><th>Other actions</th></tr></thead><tbody>${list.map(n=>`<tr><th><label class="inline"><input type="checkbox" data-select value="${esc(n)}">${esc(n)}</label></th><td>New assignee</td><td class="right"><button class="secondary" data-manager="${esc(n)}">Mark manager</button><button class="secondary" data-dismiss="${esc(n)}">Remove</button></td></tr>`).join('')||'<tr><td colspan="3">No new assignees.</td></tr>'}</tbody></table><div class="actions"><button data-add-selected>Add selected to roster</button></div></section><section class="card"><details><summary><strong>Scanner and capacity settings</strong></summary>${Object.entries(state.settings).map(([k,v])=>`<label>${esc(k)}<input data-setting="${esc(k)}" type="number" step=".01" value="${v}"></label>`).join('')}<div class="actions"><button data-save-settings>Save settings</button><button class="secondary" data-reset>Reset defaults</button></div></details></section><section class="card dangerzone"><h2>Delete all DOC data</h2><button class="danger" data-clear>Delete all data</button></section>`}
function download(name,data){const b=new Blob([data],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}

const TDD_CONFIG={
 services:[
  {name:'Evaluation',attc:40,buffer:0},
  {name:'FME: Test Plan',attc:10,buffer:0},
  {name:'FME: Evaluation',attc:42,buffer:0},
  {name:'Live Consultation',attc:10,buffer:0},
  {name:'Technical Question',attc:10,buffer:0},
  {name:'Validation',attc:15,buffer:0},
  {name:'VPAT & VPAT Update',attc:16,buffer:0},
  {name:'Demand Review',attc:10,buffer:0},
  {name:'Design Evaluation',attc:20,buffer:0}
 ],multipliers:{scoping:1.2,pageEffort:.5625,difficultyMultiplier:1,onshoreMultiplier:1,triage:.25,finalReview:.021,repSample:10},
 holidays:['2025-11-27','2025-12-25','2025-12-26'],pageBased:['FME: Evaluation']
};
function toIsoDate(date){const d=new Date(date);if(Number.isNaN(d.getTime()))return'';return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}
function tddAddBusinessDays(date,days){const d=new Date(`${toIsoDate(date)}T12:00:00`),holidays=new Set(TDD_CONFIG.holidays);let left=Math.max(0,Math.round(days));while(left){d.setDate(d.getDate()+1);const iso=toIsoDate(d);if(d.getDay()!==0&&d.getDay()!==6&&!holidays.has(iso))left--}return d}
